 static void WriteDiagnostics(Test test){var sb=new StringBuilder();sb.AppendLine("position="+cam.transform.position+" rotation="+cam.transform.rotation+" atmosphere="+JsonUtility.ToJson(a));var asm=typeof(BurtCameraData).Assembly;foreach(string n in new[]{"BurtAtmosphereUtility","BurtAtmosphereLutUtility"}){var ty=asm.GetType("Burt.RenderPipeline."+n);var method=ty.GetMethod("FormatDebugState",BindingFlags.Public|BindingFlags.Static,null,Type.EmptyTypes,null);if(method!=null)sb.AppendLine(n+"="+method.Invoke(null,null));}foreach(var m in Resources.FindObjectsOfTypeAll<Material>().Where(x=>x.shader&&x.shader.name=="Hidden/BurtRP/AtmosphereScattering")){sb.AppendLine("material="+m.name);foreach(string n in new[]{"_BurtAtmosphereSunDirection","_BurtAtmosphereSunDiskLuminanceAndCosHalfApex","_BurtAtmosphereMainLightColorOuterSpace","_BurtAtmosphereExposureParams","_BurtAtmosphereSkyLuminanceFactor"})sb.AppendLine(n+"="+m.GetVector(n));}
 foreach(var r in Resources.FindObjectsOfTypeAll<RenderTexture>().Where(x=>x.dimension==TextureDimension.Tex2D&&x.name.Contains("Atmosphere")&&x.name.Contains("Lut"))){var old=RenderTexture.active;var tex=new Texture2D(r.width,r.height,TextureFormat.RGBAFloat,false,true);try{RenderTexture.active=r;tex.ReadPixels(new Rect(0,0,r.width,r.height),0,0);tex.Apply();var pixels=tex.GetPixels();double rr=0,gg=0,bb=0;foreach(var px in pixels){rr+=px.r;gg+=px.g;bb+=px.b;}sb.AppendLine(r.name+" "+r.width+"x"+r.height+" mean="+(rr/pixels.Length)+","+(gg/pixels.Length)+","+(bb/pixels.Length));}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);}}
