 static void AppendLuts(StringBuilder sb){
 var ambient=RenderSettings.ambientProbe;sb.AppendLine("ambient="+RenderSettings.ambientMode+" color="+RenderSettings.ambientLight.ToString("R"));for(int ch=0;ch<3;ch++)for(int i=0;i<9;i++)sb.AppendLine("SH"+ch+"_"+i+"="+ambient[ch,i].ToString("R"));foreach(string n in new[]{"_BurtAmbientSHAr","_BurtAmbientSHAg","_BurtAmbientSHAb","_BurtAmbientColor","_BurtSkyReflectionHDR","_BurtSkyDiffuseCubemapHDR"})sb.AppendLine(n+"="+Shader.GetGlobalVector(n).ToString("R"));
