 foreach(var r in Resources.FindObjectsOfTypeAll<RenderTexture>().Where(x=>x.dimension==TextureDimension.Tex2D&&x.name.Contains("Atmosphere")&&x.name.Contains("LUT"))){var old=RenderTexture.active;var tex=new Texture2D(r.width,r.height,TextureFormat.RGBAFloat,false,true);try{RenderTexture.active=r;tex.ReadPixels(new Rect(0,0,r.width,r.height),0,0);tex.Apply();var pixels=tex.GetPixels();double rr=0,gg=0,bb=0;foreach(var px in pixels){rr+=px.r;gg+=px.g;bb+=px.b;}sb.AppendLine(r.name+" "+r.width+"x"+r.height+" mean="+(rr/pixels.Length)+","+(gg/pixels.Length)+","+(bb/pixels.Length));}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);}}
