 static void Save(){if(!Status.StartsWith("Running"))Time.captureDeltaTime=savedCaptureDelta;File.WriteAllText(Path.Combine(dir,"status.txt"),Status);}
 static void Guard(){if(!Application.isPlaying||!cam){Status="Interrupted";Stop();}}
 static void Stop(){RenderPipelineManager.endCameraRendering-=End;if(cam){cam.targetTexture=null;cam.cullingMask=originalMask;JsonUtility.FromJsonOverwrite(cameraJson,cd);}if(rt){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}sun.transform.rotation=sunRot;sun.intensity=lightIntensity;sun.color=lightColor;for(int i=0;i<lights.Length;i++)if(lights[i])lights[i].enabled=states[i];if(renderers!=null)for(int i=0;i<renderers.Length;i++)if(renderers[i])renderers[i].enabled=rendererStates[i];foreach(var pair in saved)JsonUtility.FromJsonOverwrite(pair.Value,pair.Key);foreach(var component in added){profile.components.Remove(component);UnityEngine.Object.DestroyImmediate(component);}QualitySettings.renderPipeline=original;UnityEngine.Object.DestroyImmediate(clone);Application.runInBackground=bg;Save();if(!Application.isEditor)Application.Quit(Status=="Completed"?0:2);}
