public sealed class BurtExposureValidationDriver : MonoBehaviour
{
    private bool started;
    private double startedAt;
    private void Update()
    {
        try
        {
            if (!started && Time.frameCount > 8)
            {
                started = true;
                startedAt = Time.realtimeSinceStartupAsDouble;
                Debug.Log("Exposure validation: " + BurtExposurePlayerValidation.Start());
            }
            if (started) BurtExposurePlayerValidation.Heartbeat();
            if (started && Time.realtimeSinceStartupAsDouble - startedAt > 600)
            {
                Debug.LogError("Exposure validation timed out: " + BurtExposurePlayerValidation.Status);
                Application.Quit(2);
            }
        }
        catch (Exception ex) { Debug.LogException(ex); Application.Quit(2); }
    }
}
#endif
